KG42.register("source_edge_archive-51b70f2a869da12481b6bacd",{"id":"15-multiagent_reverse_auction::v141-c-R009::E::v141-c-R009-E002","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R009","rule_ref":"15-multiagent_reverse_auction::v141-c-R009","record":{"edge_id":"v141-c-R009-E002","source":"coordination.price_signal","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C003"],"evidence_ids":["v141-b-g01-E08"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":[],"held_constraint_ids":["v141-c-R009-C003"],"semantic_review_status":"quarantined","source":"COMP-97d6b21fedc8f7d3","target":"COMP-a1af16dd42f1ff08","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::coordination.price_signal","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::participation.prosumer","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::coordination.price_signal","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::participation.prosumer","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"active":false,"source_signature":"3652968c19ad00b0d925c8434d85bf6fe755dd9383c31cd9167c79e87faf7ab3","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The aggregator performs price-signal coordination by announcing the utility base price for the next hour's bid solicitation. Scope: Initial bid solicitation in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. Price-signal updates are conditional on excess submitted supply: the aggregator lowers the price and requests new bids when supply exceeds demand. Scope: Iterative bidding in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. Condition: Submitted supply exceeds demand.","target_definition":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes. The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages. Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour. Algorithm 1 conditions DER bidding participation on the comparison with the utility base-price signal: bidders submit when their base price is lower and otherwise drop without participating. Scope: The initial DER participation test in Algorithm 1 for the microgrid reverse auction. Condition: The DER base price is lower than the utility base price; the alternative branch specifies nonparticipation. A bidder that is no longer interested in the new submission drops out and quits the auction for that particular hour. Scope: Continued DER participation during a rebidding round of the hourly microgrid auction. Condition: Supply exceeds demand, prompting a lower-price bidding request, and the bidder is no longer interested in the new submission.","constraints":[{"constraint_id":"v141-c-R009-C003","kind":"procedural","role":"core","statement":"Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E08"]}],"evidence":[{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-1b3df4bc99-p04-c1r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"providing the services he requires in order to achieve his m goals. If the DER is available for the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"If the DER is available for the next hour, the bidding agent decides whether to join the auction or not according to base price information received from the cost function or the state-of-charge agents."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"source_record":{"edge_id":"v141-c-R009-E002","source":"coordination.price_signal","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C003"],"evidence_ids":["v141-b-g01-E08"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}});
